System.assert(jsonEx.getStackTraceString() != '');
System.assertEquals(null, jsonEx.getCause());
JSONGenerator scalar = JSON.createGenerator(false);
scalar.writeStartArray();
scalar.writeBlob(Blob.valueOf('z'));
scalar.writeDate(Date.newInstance(2024, 3, 1));
scalar.writeDateTime(Datetime.newInstance(2024, 3, 1, 1, 2, 3));
scalar.writeId(Id.valueOf('001B000001DVM9t'));
scalar.writeNumber(Decimal.valueOf('1.25'));
scalar.writeNumber(Double.valueOf('2.5'));
