fieldGen.writeNumberField('decimalValue', Decimal.valueOf('1.25'));
fieldGen.writeNumberField('doubleValue', Double.valueOf('2.5'));
fieldGen.writeNumberField('longValue', Long.valueOf('3'));
fieldGen.writeObjectField('objectValue', new Map<String,Object>{'inner' => true});
