JSONParser strictParser = JSON.createParser('{"Name":"Strict"}');
Account strictAccount = (Account)strictParser.readValueAsStrict(Account.class);
System.assertEquals('Strict', strictAccount.Name);

JSONParser nestedReadParser = JSON.createParser('{"records":[{"Name":"Nested"}],"done":true}');
while (nestedReadParser.nextToken() != null) {
  if (nestedReadParser.getText() == 'records') {
    nestedReadParser.nextToken();
    List<Account> nestedAccounts = (List<Account>)nestedReadParser.readValueAs(List<Account>.class);
    System.assertEquals(1, nestedAccounts.size());
    System.assertEquals('Nested', nestedAccounts[0].Name);
  }
}

